// dog - a command-line DNS client
// Reimplementation based on observed behavior

mod dns;
mod output;
mod args;

use std::process;
use std::io::{self, IsTerminal};

fn main() {
    // Initialize logging based on DOG_DEBUG env var
    let debug_level = std::env::var("DOG_DEBUG").unwrap_or_default();
    if !debug_level.is_empty() {
        let level = if debug_level == "trace" { "trace" } else { "debug" };
        let filter = format!("{}={}", env!("CARGO_PKG_NAME"), level);
        env_logger::Builder::from_env(
            env_logger::Env::default().default_filter_or(&filter)
        ).init();
    }

    let exit_code = run();
    process::exit(exit_code);
}

fn run() -> i32 {
    let args: Vec<String> = std::env::args().collect();

    let opts = args::parse_options(&args[1..]);

    match opts {
        Ok(options) => {
            log::info!("Running with options -> {:?}", options);
            execute(options)
        }
        Err(e) => {
            eprintln!("dog: Invalid options: {}", e);
            3
        }
    }
}

fn execute(options: args::Options) -> i32 {
    use output::OutputFormat;

    // Determine color mode
    let use_color = match options.color {
        args::ColorMode::Always => true,
        args::ColorMode::Never => false,
        args::ColorMode::Automatic => {
            // Check if stdout is a TTY
            io::stdout().is_terminal()
        }
    };

    let mut all_responses = Vec::new();
    let mut had_error = false;
    let mut no_results = true;

    // Generate all query combinations
    let queries = options.generate_queries();

    for query in &queries {
        match perform_query(query, &options) {
            Ok(response) => {
                if !response.answers.is_empty() {
                    no_results = false;
                }
                all_responses.push(response);
            }
            Err(e) => {
                eprintln!("Error [network]: {}", e);
                had_error = true;
            }
        }
    }

    if had_error && all_responses.is_empty() {
        return 1;
    }

    // Format output
    match &options.format {
        OutputFormat::Json => {
            let output = output::format_json(&all_responses, options.measure_time);
            println!("{}", output);
        }
        OutputFormat::Text { format_durations } => {
            output::print_text(&all_responses, use_color, *format_durations, options.measure_time);
        }
        OutputFormat::Short => {
            let first = all_responses.iter()
                .flat_map(|r| r.answers.iter())
                .next();

            if let Some(answer) = first {
                for ans in all_responses.iter().flat_map(|r| r.answers.iter()) {
                    println!("{}", ans.data.short_display());
                }
                no_results = false;
            }

            if no_results {
                eprintln!("No results");
                return 2;
            }
        }
    }

    if had_error {
        1
    } else {
        0
    }
}

fn perform_query(query: &args::Query, options: &args::Options) 
    -> Result<dns::Response, String> 
{
    use std::net::{UdpSocket, TcpStream, SocketAddr};
    use std::time::{Duration, Instant};

    let nameserver = &query.nameserver;
    let port = query.port;

    let start = Instant::now();

    let request = dns::build_request(query, &options.request_params)?;

    let response_bytes = match query.transport {
        args::Transport::Udp | args::Transport::Automatic => {
            send_udp(&request, nameserver, port)?
        }
        args::Transport::Tcp => {
            send_tcp(&request, nameserver, port)?
        }
        args::Transport::Tls => {
            return Err("TLS transport not implemented".to_string());
        }
        args::Transport::Https => {
            return Err("HTTPS transport not implemented".to_string());
        }
    };

    let elapsed = start.elapsed();

    let response = dns::parse_response(&response_bytes, elapsed)?;
    Ok(response)
}

fn send_udp(data: &[u8], host: &str, port: u16) -> Result<Vec<u8>, String> {
    use std::net::UdpSocket;
    use std::time::Duration;

    log::info!("Opening UDP socket");
    let socket = UdpSocket::bind("0.0.0.0:0")
        .map_err(|e| format!("{}", e))?;
    log::debug!("Opened");

    let addr = format!("{}:{}", host, port);
    log::info!("Sending {} bytes of data to {} over UDP", data.len(), addr);
    socket.send_to(data, &addr)
        .map_err(|e| format!("{}", e))?;
    log::debug!("Wrote {} bytes", data.len());

    socket.set_read_timeout(Some(Duration::from_secs(5)))
        .map_err(|e| format!("{}", e))?;

    log::info!("Waiting to receive...");
    let mut buf = vec![0u8; 65535];
    let (len, _) = socket.recv_from(&mut buf)
        .map_err(|e| format!("{}", e))?;
    log::info!("Received {} bytes of data", len);

    buf.truncate(len);
    Ok(buf)
}

fn send_tcp(data: &[u8], host: &str, port: u16) -> Result<Vec<u8>, String> {
    use std::net::TcpStream;
    use std::io::{Write, Read};
    use std::time::Duration;

    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr)
        .map_err(|e| format!("{}", e))?;

    stream.set_read_timeout(Some(Duration::from_secs(5)))
        .map_err(|e| format!("{}", e))?;

    // DNS over TCP: 2-byte length prefix
    let len = data.len() as u16;
    stream.write_all(&len.to_be_bytes())
        .map_err(|e| format!("{}", e))?;
    stream.write_all(data)
        .map_err(|e| format!("{}", e))?;

    let mut len_buf = [0u8; 2];
    stream.read_exact(&mut len_buf)
        .map_err(|e| format!("{}", e))?;
    let response_len = u16::from_be_bytes(len_buf) as usize;

    let mut buf = vec![0u8; response_len];
    stream.read_exact(&mut buf)
        .map_err(|e| format!("{}", e))?;

    Ok(buf)
}
