fn perform_query(query: &args::Query, options: &args::Options) 
    -> Result<dns::Response, String> 
{
    use std::net::{UdpSocket, TcpStream, SocketAddr};
    use std::time::{Duration, Instant};

    let nameserver = &query.nameserver;
    let port = query.port;

    let start = Instant::now();

    let request = dns::build_request(query, &options.request_params)?;

    let response_bytes = match query.transport {
        args::Transport::Udp | args::Transport::Automatic => {
            send_udp(&request, nameserver, port)?
        }
        args::Transport::Tcp => {
            send_tcp(&request, nameserver, port)?
        }
        args::Transport::Tls => {
            return Err("TLS transport not implemented".to_string());
        }
        args::Transport::Https => {
            return Err("HTTPS transport not implemented".to_string());
        }
    };

    let elapsed = start.elapsed();

    let response = dns::parse_response(&response_bytes, elapsed)?;
    Ok(response)
}

fn send_udp(data: &[u8], host: &str, port: u16) -> Result<Vec<u8>, String> {
    use std::net::UdpSocket;
    use std::time::Duration;

    log::info!("Opening UDP socket");
    let socket = UdpSocket::bind("0.0.0.0:0")
        .map_err(|e| format!("{}", e))?;
    log::debug!("Opened");

    let addr = format!("{}:{}", host, port);
    log::info!("Sending {} bytes of data to {} over UDP", data.len(), addr);
    socket.send_to(data, &addr)
        .map_err(|e| format!("{}", e))?;
    log::debug!("Wrote {} bytes", data.len());

    socket.set_read_timeout(Some(Duration::from_secs(5)))
        .map_err(|e| format!("{}", e))?;

    log::info!("Waiting to receive...");
    let mut buf = vec![0u8; 65535];
    let (len, _) = socket.recv_from(&mut buf)
        .map_err(|e| format!("{}", e))?;
    log::info!("Received {} bytes of data", len);

    buf.truncate(len);
    Ok(buf)
}

fn send_tcp(data: &[u8], host: &str, port: u16) -> Result<Vec<u8>, String> {
    use std::net::TcpStream;
    use std::io::{Write, Read};
    use std::time::Duration;

    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr)
        .map_err(|e| format!("{}", e))?;

    stream.set_read_timeout(Some(Duration::from_secs(5)))
        .map_err(|e| format!("{}", e))?;

    // DNS over TCP: 2-byte length prefix
    let len = data.len() as u16;
    stream.write_all(&len.to_be_bytes())
        .map_err(|e| format!("{}", e))?;
    stream.write_all(data)
        .map_err(|e| format!("{}", e))?;

    let mut len_buf = [0u8; 2];
    stream.read_exact(&mut len_buf)
        .map_err(|e| format!("{}", e))?;
    let response_len = u16::from_be_bytes(len_buf) as usize;

    let mut buf = vec![0u8; response_len];
    stream.read_exact(&mut buf)
        .map_err(|e| format!("{}", e))?;

    Ok(buf)
}
