    opts.optflag("v", "version", "Show version");

    let matches = opts.parse(args)
        .map_err(|e| e.to_string())?;

    // Handle help/version
    if matches.opt_present("help") {
        print_help();
        std::process::exit(0);
    }

    if matches.opt_present("version") {
        print_version();
        std::process::exit(0);
    }

    // Parse free arguments (positional)
    let mut free_domains: Vec<String> = Vec::new();
    let mut free_types: Vec<u16> = Vec::new();
    let mut free_classes: Vec<u16> = Vec::new();
    let mut free_nameservers: Vec<(String, u16)> = Vec::new();

    for arg in &matches.free {
        if arg.starts_with('@') {
            let ns_str = &arg[1..];
            free_nameservers.push(parse_nameserver(ns_str));
