    Short,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Transport {
    Udp,
    Tcp,
    Tls,
    Https,
    Automatic,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum EdnsMode {
    Disable,
    Hide,
    Show,
}

#[derive(Debug, Clone)]
pub struct ProtocolTweaks {
    pub set_authoritative_flag: bool,
    pub set_authentic_flag: bool,
    pub set_checking_disabled_flag: bool,
    pub udp_payload_size: Option<u16>,
}

impl Default for ProtocolTweaks {
    fn default() -> Self {
        ProtocolTweaks {
            set_authoritative_flag: false,
            set_authentic_flag: false,
            set_checking_disabled_flag: false,
            udp_payload_size: None,
        }
    }
}

#[derive(Debug, Clone)]
pub struct RequestParams {
    pub edns: EdnsMode,
    pub txid: Option<u16>,
    pub tweaks: ProtocolTweaks,
}

#[derive(Debug, Clone)]
pub struct Options {
    pub domains: Vec<String>,
    pub record_types: Vec<u16>,
    pub classes: Vec<u16>,
    pub nameservers: Vec<(String, u16)>,  // (host, port)
    pub transports: Vec<Transport>,
    pub format: OutputFormat,
    pub color: ColorMode,
    pub measure_time: bool,
    pub request_params: RequestParams,
}

#[derive(Debug, Clone)]
pub struct Query {
    pub domain: String,
    pub record_type: u16,
    pub class: u16,
    pub nameserver: String,
    pub port: u16,
    pub transport: Transport,
}

impl Options {
    pub fn generate_queries(&self) -> Vec<Query> {
        let mut queries = Vec::new();

        for domain in &self.domains {
            for &rtype in &self.record_types {
                for &class in &self.classes {
                    for (ns, port) in &self.nameservers {
                        for &transport in &self.transports {
                            queries.push(Query {
                                domain: domain.clone(),
                                record_type: rtype,
                                class,
                                nameserver: ns.clone(),
                                port: *port,
                                transport,
                            });
                        }
                    }
                }
            }
        }

        queries
    }
}

// Record types
pub const TYPE_A: u16 = 1;
pub const TYPE_NS: u16 = 2;
pub const TYPE_CNAME: u16 = 5;
pub const TYPE_SOA: u16 = 6;
pub const TYPE_PTR: u16 = 12;
pub const TYPE_HINFO: u16 = 13;
pub const TYPE_MX: u16 = 15;
pub const TYPE_TXT: u16 = 16;
pub const TYPE_AAAA: u16 = 28;
pub const TYPE_LOC: u16 = 29;
pub const TYPE_SRV: u16 = 33;
pub const TYPE_NAPTR: u16 = 35;
pub const TYPE_OPT: u16 = 41;
pub const TYPE_SSHFP: u16 = 44;
pub const TYPE_TLSA: u16 = 52;
pub const TYPE_CAA: u16 = 257;

// Classes
pub const CLASS_IN: u16 = 1;
pub const CLASS_CH: u16 = 3;
pub const CLASS_HS: u16 = 4;

fn type_name_to_id(name: &str) -> Option<u16> {
    match name.to_uppercase().as_str() {
        "A" => Some(TYPE_A),
        "NS" => Some(TYPE_NS),
        "CNAME" => Some(TYPE_CNAME),
        "SOA" => Some(TYPE_SOA),
        "PTR" => Some(TYPE_PTR),
        "HINFO" => Some(TYPE_HINFO),
        "MX" => Some(TYPE_MX),
        "TXT" => Some(TYPE_TXT),
        "AAAA" => Some(TYPE_AAAA),
        "LOC" => Some(TYPE_LOC),
        "SRV" => Some(TYPE_SRV),
        "NAPTR" => Some(TYPE_NAPTR),
        "OPT" => Some(TYPE_OPT),
        "SSHFP" => Some(TYPE_SSHFP),
        "TLSA" => Some(TYPE_TLSA),
        "CAA" => Some(TYPE_CAA),
        // Known but not fully interpreted types
        "ANY" => Some(255),
        "AXFR" => Some(252),
        "IXFR" => Some(251),
        "AFSDB" => Some(18),
        "CERT" => Some(37),
        "DS" => Some(43),
        "RRSIG" => Some(46),
