        "DNAME" => Some(39),
        "APL" => Some(42),
        "IPSECKEY" => Some(45),
        "DHCID" => Some(49),
        "HIP" => Some(55),
        "NINFO" => Some(56),
        "CDS" => Some(59),
        "CDNSKEY" => Some(60),
        "OPENPGPKEY" => Some(61),
        "CSYNC" => Some(62),
        "ZONEMD" => Some(63),
        "SVCB" => Some(64),
        "HTTPS" => Some(65),
        "EUI48" => Some(108),
        "EUI64" => Some(109),
        "TKEY" => Some(249),
        "TSIG" => Some(250),
        "URI" => Some(256),
        _ => None,
    }
}

fn class_name_to_id(name: &str) -> Option<u16> {
    match name.to_uppercase().as_str() {
        "IN" => Some(CLASS_IN),
        "CH" => Some(CLASS_CH),
        "HS" => Some(CLASS_HS),
        _ => None,
    }
}

pub fn get_system_nameservers() -> Result<Vec<(String, u16)>, String> {
    // Read /etc/resolv.conf
    let content = std::fs::read_to_string("/etc/resolv.conf")
        .map_err(|e| format!("Failed to read /etc/resolv.conf: {}", e))?;

    let mut servers = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("nameserver") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                servers.push((parts[1].to_string(), 53));
            }
        }
    }

    if servers.is_empty() {
        Err("No nameservers found in /etc/resolv.conf".to_string())
    } else {
        Ok(servers)
    }
}

fn parse_nameserver(s: &str) -> (String, u16) {
    // Try to parse as host:port
    if let Some(idx) = s.rfind(':') {
        let host = &s[..idx];
        let port_str = &s[idx+1..];
        if let Ok(port) = port_str.parse::<u16>() {
            return (host.to_string(), port);
        }
    }
    (s.to_string(), 53)
}

fn looks_like_nameserver(s: &str) -> bool {
    s.starts_with('@')
}

fn looks_like_type(s: &str) -> bool {
    type_name_to_id(s).is_some()
}

fn looks_like_class(s: &str) -> bool {
    class_name_to_id(s).is_some()
}

fn is_valid_domain_char(c: char) -> bool {
    c.is_alphanumeric() || c == '.' || c == '-' || c == '_' 
}

fn looks_like_domain(s: &str) -> bool {
    !s.is_empty() && s.chars().all(|c| is_valid_domain_char(c))
        && !looks_like_type(s) && !looks_like_class(s)
}

pub fn parse_options(args: &[String]) -> Result<Options, String> {
    let mut opts = getopts::Options::new();

    opts.optopt("q", "query", "Domain to query", "HOST");
    opts.optopt("t", "type", "Record type", "TYPE");
    opts.optopt("n", "nameserver", "Nameserver", "ADDR");
    opts.optopt("", "class", "DNS class", "CLASS");
    opts.optopt("", "edns", "EDNS setting", "SETTING");
    opts.optopt("", "txid", "Transaction ID", "NUMBER");
    opts.optmulti("Z", "", "Protocol tweaks", "TWEAKS");
    opts.optflag("U", "udp", "Use UDP");
    opts.optflag("T", "tcp", "Use TCP");
    opts.optflag("S", "tls", "Use TLS");
    opts.optflag("H", "https", "Use HTTPS");
    opts.optflag("1", "short", "Short mode");
    opts.optflag("J", "json", "JSON output");
    opts.optopt("", "color", "Color mode", "WHEN");
    opts.optopt("", "colour", "Color mode", "WHEN");
    opts.optflag("", "seconds", "Show TTL as seconds");
    opts.optflag("", "time", "Show response time");
    opts.optflag("?", "help", "Show help");
    opts.optflag("v", "version", "Show version");

    let matches = opts.parse(args)
        .map_err(|e| e.to_string())?;

    // Handle help/version
    if matches.opt_present("help") {
        print_help();
        std::process::exit(0);
    }

    if matches.opt_present("version") {
        print_version();
        std::process::exit(0);
    }

    // Parse free arguments (positional)
    let mut free_domains: Vec<String> = Vec::new();
    let mut free_types: Vec<u16> = Vec::new();
    let mut free_classes: Vec<u16> = Vec::new();
    let mut free_nameservers: Vec<(String, u16)> = Vec::new();

    for arg in &matches.free {
        if arg.starts_with('@') {
            let ns_str = &arg[1..];
            free_nameservers.push(parse_nameserver(ns_str));
        } else if let Some(type_id) = type_name_to_id(arg) {
            free_types.push(type_id);
        } else if let Some(class_id) = class_name_to_id(arg) {
            free_classes.push(class_id);
        } else {
            // Treat as domain
            log::trace!("Got domain -> {:?}", arg);
            free_domains.push(arg.clone());
        }
    }

    // Merge with explicit options
    let mut domains = free_domains;
    if let Some(q) = matches.opt_str("query") {
        domains.push(q);
    }

    let mut types = free_types;
    if let Some(t) = matches.opt_str("type") {
        let type_id = type_name_to_id(&t)
            .ok_or_else(|| format!("Unknown record type: {}", t))?;
        types.push(type_id);
    }

    let mut classes = free_classes;
    if let Some(c) = matches.opt_str("class") {
        let class_id = class_name_to_id(&c)
            .ok_or_else(|| format!("Unknown class: {}", c))?;
        classes.push(class_id);
    }

    let mut nameservers = free_nameservers;
    if let Some(n) = matches.opt_str("nameserver") {
        nameservers.push(parse_nameserver(&n));
    }

    // Defaults
    if types.is_empty() {
        types.push(TYPE_A);
    }
    if classes.is_empty() {
        classes.push(CLASS_IN);
    }

    // If no domains and no nameserver specified, show help and exit
    if domains.is_empty() {
        print_help();
        std::process::exit(3);
    }

    if nameservers.is_empty() {
        nameservers = get_system_nameservers()
            .map_err(|e| format!("Failed to get system nameservers: {}", e))?;
    }

    // Transports
    let mut transports = Vec::new();
    if matches.opt_present("udp") {
        transports.push(Transport::Udp);
    }
    if matches.opt_present("tcp") {
        transports.push(Transport::Tcp);
    }
    if matches.opt_present("tls") {
        transports.push(Transport::Tls);
    }
    if matches.opt_present("https") {
        transports.push(Transport::Https);
    }
    if transports.is_empty() {
        transports.push(Transport::Automatic);
    }

    // Output format
    let format_durations = !matches.opt_present("seconds");
    let format = if matches.opt_present("short") {
        OutputFormat::Short
    } else if matches.opt_present("json") {
        OutputFormat::Json
    } else {
        OutputFormat::Text { format_durations }
    };

    // Color mode
    let color_str = matches.opt_str("colour")
        .or_else(|| matches.opt_str("color"))
        .unwrap_or_else(|| "automatic".to_string());

    let color = match color_str.to_lowercase().as_str() {
        "always" => ColorMode::Always,
        "never" => ColorMode::Never,
        _ => ColorMode::Automatic,
    };

    // EDNS
    let edns = match matches.opt_str("edns").as_deref() {
        Some("disable") => EdnsMode::Disable,
        Some("show") => EdnsMode::Show,
        _ => EdnsMode::Hide,
    };

    // txid
    let txid = matches.opt_str("txid")
        .and_then(|s| s.parse::<u16>().ok());

    // Tweaks
    let mut tweaks = ProtocolTweaks::default();
    for z in matches.opt_strs("Z") {
        match z.as_str() {
            "aa" => tweaks.set_authoritative_flag = true,
            "ad" => tweaks.set_authentic_flag = true,
            "cd" => tweaks.set_checking_disabled_flag = true,
            s if s.starts_with("bufsize=") => {
                if let Ok(size) = s[8..].parse::<u16>() {
                    tweaks.udp_payload_size = Some(size);
                }
            }
            _ => {}
        }
    }

    let measure_time = matches.opt_present("time");

    Ok(Options {
        domains,
        record_types: types,
        classes,
        nameservers,
        transports,
        format,
        color,
        measure_time,
        request_params: RequestParams {
            edns,
            txid,
            tweaks,
        },
    })
}

