use std::net::{Ipv4Addr, Ipv6Addr};
use std::time::Duration;
use crate::args::{RequestParams, EdnsMode, Query};

#[derive(Debug, Clone)]
pub struct Response {
    pub query_name: String,
    pub query_type: u16,
    pub query_class: u16,
    pub answers: Vec<Record>,
    pub authorities: Vec<Record>,
    pub additionals: Vec<Record>,
    pub rcode: u8,
    pub elapsed: Duration,
}

#[derive(Debug, Clone)]
pub struct Record {
    pub name: String,
    pub rtype: u16,
    pub class: u16,
    pub ttl: u32,
    pub data: RecordData,
    pub section: Section,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Section {
    Answer,
    Authority,
    Additional,
}

#[derive(Debug, Clone)]
pub enum RecordData {
    A(Ipv4Addr),
    Aaaa(Ipv6Addr),
    Ns(String),
    Cname(String),
    Ptr(String),
    Mx { preference: u16, exchange: String },
    Txt(Vec<Vec<u8>>),
    Soa {
        mname: String,
        rname: String,
        serial: u32,
        refresh: u32,
        retry: u32,
        expire: u32,
        minimum: u32,
    },
    Srv {
        priority: u16,
        weight: u16,
        port: u16,
        target: String,
    },
    Caa {
        critical: bool,
        tag: String,
        value: String,
    },
    Naptr {
        order: u16,
        preference: u16,
        flags: String,
        service: String,
        regexp: String,
        replacement: String,
    },
    Opt {
        udp_payload_size: u16,
        extended_rcode: u8,
        version: u8,
        flags: u16,
        options: Vec<(u16, Vec<u8>)>,
    },
    Sshfp {
        algorithm: u8,
        fp_type: u8,
        fingerprint: Vec<u8>,
    },
    Tlsa {
        cert_usage: u8,
        selector: u8,
        matching_type: u8,
        cert_data: Vec<u8>,
    },
    Hinfo {
        cpu: String,
        os: String,
    },
    Unknown { type_num: u16, data: Vec<u8> },
}

impl RecordData {
    pub fn short_display(&self) -> String {
        match self {
            RecordData::A(ip) => ip.to_string(),
            RecordData::Aaaa(ip) => ip.to_string(),
            RecordData::Ns(name) => name.clone(),
            RecordData::Cname(name) => name.clone(),
            RecordData::Ptr(name) => name.clone(),
            RecordData::Mx { exchange, .. } => exchange.clone(),
            RecordData::Txt(parts) => {
                let s = parts.iter()
                    .map(|p| String::from_utf8_lossy(p).to_string())
                    .collect::<Vec<_>>()
                    .join("");
                s
            }
            RecordData::Soa { mname, .. } => mname.clone(),
            RecordData::Srv { target, port, .. } => format!("{}:{}", target, port),
            RecordData::Caa { value, .. } => value.clone(),
            RecordData::Naptr { replacement, .. } => replacement.clone(),
            _ => String::new(),
        }
    }
}

pub fn build_request(query: &Query, params: &RequestParams) -> Result<Vec<u8>, String> {
    let mut buf = Vec::new();

    // Transaction ID
    let txid: u16 = if let Some(id) = params.txid {
        id
    } else {
        rand::random()
    };

    buf.push((txid >> 8) as u8);
    buf.push((txid & 0xff) as u8);

    // Flags
    let mut flags: u16 = 0x0100; // RD (recursion desired)
    if params.tweaks.set_authoritative_flag {
        flags |= 0x0400; // AA
    }
    if params.tweaks.set_authentic_flag {
        flags |= 0x0020; // AD
    }
    if params.tweaks.set_checking_disabled_flag {
        flags |= 0x0010; // CD
    }

    buf.push((flags >> 8) as u8);
    buf.push((flags & 0xff) as u8);

    // QDCOUNT = 1
    buf.push(0); buf.push(1);
    // ANCOUNT = 0
    buf.push(0); buf.push(0);
    // NSCOUNT = 0
    buf.push(0); buf.push(0);
    // ARCOUNT
    let has_opt = params.edns != EdnsMode::Disable;
    if has_opt {
        buf.push(0); buf.push(1);
    } else {
        buf.push(0); buf.push(0);
    }

    // Question section
    encode_domain_name(&mut buf, &query.domain);
    buf.push((query.record_type >> 8) as u8);
    buf.push((query.record_type & 0xff) as u8);
    buf.push((query.class >> 8) as u8);
    buf.push((query.class & 0xff) as u8);

    // OPT record if EDNS enabled
    if has_opt {
        // Name: root (0)
        buf.push(0);
        // Type: OPT (41)
        buf.push(0); buf.push(41);
        // UDP payload size (class field)
        let udp_size = params.tweaks.udp_payload_size.unwrap_or(4096);
        buf.push((udp_size >> 8) as u8);
        buf.push((udp_size & 0xff) as u8);
        // Extended RCODE and flags (TTL field)
        buf.push(0); buf.push(0); buf.push(0); buf.push(0);
        // RDLENGTH = 0
        buf.push(0); buf.push(0);
    }

    Ok(buf)
}

fn encode_domain_name(buf: &mut Vec<u8>, name: &str) {
    let name = name.trim_end_matches('.');
    if name.is_empty() {
        buf.push(0);
        return;
    }
    for label in name.split('.') {
        let bytes = label.as_bytes();
        buf.push(bytes.len() as u8);
        buf.extend_from_slice(bytes);
    }
    buf.push(0);
}

pub fn parse_response(data: &[u8], elapsed: Duration) -> Result<Response, String> {
    log::info!("Parsing response");
    log::trace!("Bytes -> {:?}", data);

    if data.len() < 12 {
        return Err("Response too short".to_string());
    }

    let mut pos = 0;

    let _txid = read_u16(data, &mut pos);
    let flags = read_u16(data, &mut pos);
    let qdcount = read_u16(data, &mut pos) as usize;
    let ancount = read_u16(data, &mut pos) as usize;
    let nscount = read_u16(data, &mut pos) as usize;
    let arcount = read_u16(data, &mut pos) as usize;

    let rcode = (flags & 0x000f) as u8;

    let mut query_name = String::new();
    let mut query_type = 0u16;
    let mut query_class = 0u16;

    // Parse questions
    for _ in 0..qdcount {
        let (name, new_pos) = read_domain_name(data, pos)?;
        pos = new_pos;
        query_name = name;
        query_type = read_u16(data, &mut pos);
        query_class = read_u16(data, &mut pos);
    }

    // Parse answer records
    let mut answers = Vec::new();
    for _ in 0..ancount {
        let (record, new_pos) = parse_record(data, pos, Section::Answer)?;
        pos = new_pos;
        answers.push(record);
    }

    // Parse authority records
    let mut authorities = Vec::new();
    for _ in 0..nscount {
        let (record, new_pos) = parse_record(data, pos, Section::Authority)?;
        pos = new_pos;
        authorities.push(record);
    }

    // Parse additional records
    let mut additionals = Vec::new();
    for _ in 0..arcount {
        let (record, new_pos) = parse_record(data, pos, Section::Additional)?;
        pos = new_pos;
        additionals.push(record);
    }

    Ok(Response {
        query_name,
        query_type,
        query_class,
        answers,
        authorities,
        additionals,
        rcode,
        elapsed,
    })
}

fn parse_record(data: &[u8], pos: usize, section: Section) -> Result<(Record, usize), String> {
    let mut pos = pos;

    let (name, new_pos) = read_domain_name(data, pos)?;
    pos = new_pos;

    if pos + 10 > data.len() {
        return Err("Record truncated".to_string());
    }

    let rtype = read_u16(data, &mut pos);

    // Special handling for OPT record (type 41)
    if rtype == 41 {
        // OPT: class field = UDP payload size, TTL = extended RCODE + version + flags
        let udp_payload_size = read_u16(data, &mut pos);
        let extended_rcode = data[pos];
        let version = data[pos + 1];
        let flags = read_u16_at(data, pos + 2);
        pos += 4;
        let rdlength = read_u16(data, &mut pos) as usize;

        let mut options = Vec::new();
        let rdata_end = pos + rdlength;
        while pos + 4 <= rdata_end {
            let opt_code = read_u16(data, &mut pos);
            let opt_len = read_u16(data, &mut pos) as usize;
            if pos + opt_len <= rdata_end {
                let opt_data = data[pos..pos+opt_len].to_vec();
                options.push((opt_code, opt_data));
                pos += opt_len;
            } else {
                break;
            }
        }
        pos = rdata_end;

        return Ok((Record {
            name,
            rtype,
            class: udp_payload_size,
            ttl: 0,
            data: RecordData::Opt {
                udp_payload_size,
                extended_rcode,
                version,
                flags,
                options,
            },
            section,
        }, pos));
    }

    let class = read_u16(data, &mut pos);
    let ttl = read_u32(data, &mut pos);
    let rdlength = read_u16(data, &mut pos) as usize;

    if pos + rdlength > data.len() {
        return Err(format!("Record data truncated: need {} bytes, have {}", rdlength, data.len() - pos));
    }

    let rdata = &data[pos..pos+rdlength];
    let rdata_start = pos;

    let record_data = match rtype {
        1 => { // A
            if rdlength != 4 {
                return Err("Invalid A record length".to_string());
            }
            let ip = Ipv4Addr::new(rdata[0], rdata[1], rdata[2], rdata[3]);
            RecordData::A(ip)
        }
        28 => { // AAAA
            if rdlength != 16 {
                return Err("Invalid AAAA record length".to_string());
            }
            let mut bytes = [0u8; 16];
            bytes.copy_from_slice(rdata);
            RecordData::Aaaa(Ipv6Addr::from(bytes))
        }
        2 => { // NS
            let (name, _) = read_domain_name(data, pos)?;
            RecordData::Ns(name)
        }
        5 => { // CNAME
            let (name, _) = read_domain_name(data, pos)?;
            RecordData::Cname(name)
        }
        12 => { // PTR
            let (name, _) = read_domain_name(data, pos)?;
            RecordData::Ptr(name)
        }
        15 => { // MX
            if rdlength < 2 {
                return Err("Invalid MX record".to_string());
            }
            let preference = read_u16_at(rdata, 0);
            let (exchange, _) = if rdlength > 2 {
                read_domain_name(data, pos + 2)?
            } else {
                ("".to_string(), pos + 2)
            };
            RecordData::Mx { preference, exchange }
        }
        16 => { // TXT
            let mut parts = Vec::new();
            let mut i = 0;
            while i < rdlength {
                let len = rdata[i] as usize;
                i += 1;
                if i + len <= rdlength {
                    parts.push(rdata[i..i+len].to_vec());
                    i += len;
                } else {
                    break;
                }
            }
            RecordData::Txt(parts)
        }
        6 => { // SOA
            let (mname, new_pos) = read_domain_name(data, pos)?;
            let (rname, new_pos) = read_domain_name(data, new_pos)?;
            let mut p = new_pos - rdata_start;
            if p + 20 <= rdlength {
                let serial = read_u32_at(rdata, p);
                let refresh = read_u32_at(rdata, p + 4);
                let retry = read_u32_at(rdata, p + 8);
                let expire = read_u32_at(rdata, p + 12);
                let minimum = read_u32_at(rdata, p + 16);
                RecordData::Soa { mname, rname, serial, refresh, retry, expire, minimum }
            } else {
                RecordData::Soa { mname, rname, serial: 0, refresh: 0, retry: 0, expire: 0, minimum: 0 }
            }
        }
        33 => { // SRV
            if rdlength < 6 {
                return Err("Invalid SRV record".to_string());
            }
            let priority = read_u16_at(rdata, 0);
            let weight = read_u16_at(rdata, 2);
            let port = read_u16_at(rdata, 4);
            let (target, _) = read_domain_name(data, pos + 6)?;
            RecordData::Srv { priority, weight, port, target }
        }
        257 => { // CAA
            if rdlength < 2 {
                return Err("Invalid CAA record".to_string());
            }
            let flags = rdata[0];
            let critical = (flags & 0x80) != 0;
            let tag_len = rdata[1] as usize;
            if 2 + tag_len > rdlength {
                return Err("Invalid CAA record".to_string());
            }
            let tag = String::from_utf8_lossy(&rdata[2..2+tag_len]).to_string();
            let value = String::from_utf8_lossy(&rdata[2+tag_len..rdlength]).to_string();
            RecordData::Caa { critical, tag, value }
        }
        35 => { // NAPTR
            if rdlength < 4 {
                return Err("Invalid NAPTR record".to_string());
            }
            let order = read_u16_at(rdata, 0);
            let preference = read_u16_at(rdata, 2);
            let mut i = 4;

            let flags = read_char_string(rdata, &mut i);
            let service = read_char_string(rdata, &mut i);
            let regexp = read_char_string(rdata, &mut i);

            let (replacement, _) = read_domain_name(data, pos + i)?;

            RecordData::Naptr {
                order,
                preference,
                flags: String::from_utf8_lossy(&flags).to_string(),
                service: String::from_utf8_lossy(&service).to_string(),
                regexp: String::from_utf8_lossy(&regexp).to_string(),
                replacement,
            }
        }
        44 => { // SSHFP
            if rdlength < 2 {
                return Err("Invalid SSHFP record".to_string());
            }
            let algorithm = rdata[0];
            let fp_type = rdata[1];
            let fingerprint = rdata[2..].to_vec();
            RecordData::Sshfp { algorithm, fp_type, fingerprint }
        }
        52 => { // TLSA
            if rdlength < 3 {
                return Err("Invalid TLSA record".to_string());
            }
            let cert_usage = rdata[0];
            let selector = rdata[1];
            let matching_type = rdata[2];
            let cert_data = rdata[3..].to_vec();
            RecordData::Tlsa { cert_usage, selector, matching_type, cert_data }
        }
        13 => { // HINFO
            let mut i = 0;
            let cpu_bytes = read_char_string(rdata, &mut i);
            let os_bytes = read_char_string(rdata, &mut i);
            RecordData::Hinfo {
                cpu: String::from_utf8_lossy(&cpu_bytes).to_string(),
                os: String::from_utf8_lossy(&os_bytes).to_string(),
            }
        }
        _ => {
            RecordData::Unknown { type_num: rtype, data: rdata.to_vec() }
        }
    };

    pos += rdlength;

    Ok((Record {
        name,
        rtype,
        class,
        ttl,
        data: record_data,
        section,
    }, pos))
}

fn read_char_string(data: &[u8], pos: &mut usize) -> Vec<u8> {
    if *pos >= data.len() {
        return Vec::new();
    }
    let len = data[*pos] as usize;
    *pos += 1;
    if *pos + len <= data.len() {
        let result = data[*pos..*pos + len].to_vec();
        *pos += len;
        result
    } else {
        Vec::new()
    }
}

fn read_u16(data: &[u8], pos: &mut usize) -> u16 {
    let val = ((data[*pos] as u16) << 8) | (data[*pos + 1] as u16);
    *pos += 2;
    val
}

fn read_u16_at(data: &[u8], pos: usize) -> u16 {
    ((data[pos] as u16) << 8) | (data[pos + 1] as u16)
}

fn read_u32(data: &[u8], pos: &mut usize) -> u32 {
    let val = ((data[*pos] as u32) << 24) 
        | ((data[*pos + 1] as u32) << 16) 
        | ((data[*pos + 2] as u32) << 8) 
        | (data[*pos + 3] as u32);
    *pos += 4;
    val
}

fn read_u32_at(data: &[u8], pos: usize) -> u32 {
    ((data[pos] as u32) << 24) 
        | ((data[pos + 1] as u32) << 16) 
        | ((data[pos + 2] as u32) << 8) 
        | (data[pos + 3] as u32)
}

fn read_domain_name(data: &[u8], start: usize) -> Result<(String, usize), String> {
    let mut parts = Vec::new();
    let mut pos = start;
    let mut end_pos = None;
    let mut followed_pointer = false;

    loop {
        if pos >= data.len() {
            return Err("Domain name truncated".to_string());
        }

        let label_len = data[pos];

        if label_len == 0 {
            pos += 1;
            break;
        }

        // Check for pointer (top two bits set)
        if (label_len & 0xc0) == 0xc0 {
            if pos + 1 >= data.len() {
                return Err("Invalid pointer".to_string());
            }
            let ptr = ((label_len & 0x3f) as usize) << 8 | (data[pos + 1] as usize);
            if end_pos.is_none() {
                end_pos = Some(pos + 2);
            }
            pos = ptr;
            followed_pointer = true;
        } else {
            let len = label_len as usize;
            pos += 1;
            if pos + len > data.len() {
                return Err("Label truncated".to_string());
            }
            parts.push(String::from_utf8_lossy(&data[pos..pos+len]).to_string());
            pos += len;
        }
    }

    if end_pos.is_none() {
        end_pos = Some(pos);
    }

    let name = if parts.is_empty() {
        ".".to_string()
    } else {
        format!("{}.", parts.join("."))
    };

    Ok((name, end_pos.unwrap()))
}
