pub fn build_request(query: &Query, params: &RequestParams) -> Result<Vec<u8>, String> {
    let mut buf = Vec::new();

    // Transaction ID
    let txid: u16 = if let Some(id) = params.txid {
        id
    } else {
        rand::random()
    };

    buf.push((txid >> 8) as u8);
    buf.push((txid & 0xff) as u8);

    // Flags
    let mut flags: u16 = 0x0100; // RD (recursion desired)
    if params.tweaks.set_authoritative_flag {
        flags |= 0x0400; // AA
    }
    if params.tweaks.set_authentic_flag {
        flags |= 0x0020; // AD
    }
    if params.tweaks.set_checking_disabled_flag {
        flags |= 0x0010; // CD
    }

    buf.push((flags >> 8) as u8);
    buf.push((flags & 0xff) as u8);

    // QDCOUNT = 1
    buf.push(0); buf.push(1);
    // ANCOUNT = 0
    buf.push(0); buf.push(0);
    // NSCOUNT = 0
    buf.push(0); buf.push(0);
    // ARCOUNT
    let has_opt = params.edns != EdnsMode::Disable;
    if has_opt {
        buf.push(0); buf.push(1);
    } else {
        buf.push(0); buf.push(0);
    }

    // Question section
    encode_domain_name(&mut buf, &query.domain);
    buf.push((query.record_type >> 8) as u8);
    buf.push((query.record_type & 0xff) as u8);
    buf.push((query.class >> 8) as u8);
    buf.push((query.class & 0xff) as u8);

    // OPT record if EDNS enabled
    if has_opt {
        // Name: root (0)
        buf.push(0);
        // Type: OPT (41)
        buf.push(0); buf.push(41);
        // UDP payload size (class field)
        let udp_size = params.tweaks.udp_payload_size.unwrap_or(4096);
        buf.push((udp_size >> 8) as u8);
        buf.push((udp_size & 0xff) as u8);
        // Extended RCODE and flags (TTL field)
        buf.push(0); buf.push(0); buf.push(0); buf.push(0);
        // RDLENGTH = 0
        buf.push(0); buf.push(0);
    }

    Ok(buf)
