        5 => "CNAME".to_string(),
        6 => "SOA".to_string(),
        12 => "PTR".to_string(),
        13 => "HINFO".to_string(),
        15 => "MX".to_string(),
        16 => "TXT".to_string(),
        28 => "AAAA".to_string(),
        29 => "LOC".to_string(),
        33 => "SRV".to_string(),
        35 => "NAPTR".to_string(),
        41 => "OPT".to_string(),
        44 => "SSHFP".to_string(),
        52 => "TLSA".to_string(),
        257 => "CAA".to_string(),
        _ => type_num.to_string(),
    }
}

pub fn class_name(class_num: u16) -> String {
    match class_num {
        1 => "IN".to_string(),
        3 => "CH".to_string(),
        4 => "HS".to_string(),
        _ => class_num.to_string(),
    }
}

pub fn format_ttl(ttl: u32, format_durations: bool) -> String {
    if !format_durations {
        return ttl.to_string();
    }

    if ttl == 0 {
        return "0s".to_string();
    }

    let mut remaining = ttl;
    let mut parts = Vec::new();

    let days = remaining / 86400;
    remaining %= 86400;
    let hours = remaining / 3600;
    remaining %= 3600;
    let minutes = remaining / 60;
    let seconds = remaining % 60;

    if days > 0 {
        parts.push(format!("{}d", days));
        parts.push(format!("{:02}h", hours));
        parts.push(format!("{:02}m", minutes));
        parts.push(format!("{:02}s", seconds));
    } else if hours > 0 {
        parts.push(format!("{}h", hours));
        parts.push(format!("{:02}m", minutes));
        parts.push(format!("{:02}s", seconds));
    } else if minutes > 0 {
        parts.push(format!("{}m", minutes));
        parts.push(format!("{:02}s", seconds));
    } else {
        parts.push(format!("{}s", seconds));
    }

    parts.join("")
}

fn format_record_data(data: &RecordData, format_durations: bool) -> String {
