        RecordData::Aaaa(ip) => ip.to_string(),
        RecordData::Ns(name) => format!("\"{}\"", name),
        RecordData::Cname(name) => format!("\"{}\"", name),
        RecordData::Ptr(name) => format!("\"{}\"", name),
        RecordData::Mx { preference, exchange } => {
            format!("{} \"{}\"", preference, exchange)
        }
        RecordData::Txt(parts) => {
            parts.iter()
                .map(|p| format!("\"{}\"", escape_txt(p)))
                .collect::<Vec<_>>()
                .join(" ")
        }
        RecordData::Soa { mname, rname, serial, refresh, retry, expire, minimum } => {
            format!("\"{}\" \"{}\" {} {} {} {} {}",
                mname, rname, serial,
                format_ttl(*refresh, format_durations),
                format_ttl(*retry, format_durations),
                format_ttl(*expire, format_durations),
                format_ttl(*minimum, format_durations),
            )
        }
        RecordData::Srv { priority, weight, port, target } => {
            format!("{} {} \"{}\":{}", priority, weight, target, port)
        }
        RecordData::Caa { critical, tag, value } => {
            let critical_str = if *critical { "(critical)" } else { "(non-critical)" };
            format!("\"{}\" \"{}\" {}", tag, value, critical_str)
        }
        RecordData::Naptr { order, preference, flags, service, regexp, replacement } => {
            format!("{} {} \"{}\" \"{}\" \"{}\" \"{}\"",
                order, preference, flags, service, regexp, replacement)
        }
        RecordData::Sshfp { algorithm, fp_type, fingerprint } => {
            format!("{} {} {}", algorithm, fp_type, hex::encode(fingerprint))
        }
        RecordData::Tlsa { cert_usage, selector, matching_type, cert_data } => {
            format!("{} {} {} {}", cert_usage, selector, matching_type, hex::encode(cert_data))
        }
        RecordData::Hinfo { cpu, os } => {
            format!("\"{}\" \"{}\"", cpu, os)
        }
        RecordData::Opt { udp_payload_size, extended_rcode, version, flags, options } => {
            // Should not reach here in normal text output
            format!("+ {} {} {} {} []", udp_payload_size, extended_rcode, version, flags)
        }
        RecordData::Unknown { type_num, data } => {
            // Display as sequence of numbers
            data.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(" ")
        }
    }
}

fn escape_txt(data: &[u8]) -> String {
    String::from_utf8_lossy(data)
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
