            let colored_name = format!("\x1b[1;34m{}\x1b[0m", record.name);
            // Need to reconstruct with coloring but maintain alignment
            print!("{}", " ".repeat(type_width - type_str.len()));
            print!("{}", colored_type);
            print!(" {}", colored_name);
            // pad domain
            let pad = domain_width.saturating_sub(record.name.len());
            print!("{}", " ".repeat(pad));
            print!(" {}{}", ttl_padded, section_marker);
            println!("{}", data_str);
        } else {
            println!("{} {} {}{}{}", type_padded, domain_padded, ttl_padded, section_marker, data_str);
        }
    }

    // Print OPT records
    for &(record, _) in &opt_records {
        if let RecordData::Opt { udp_payload_size, extended_rcode, version, flags, options } = &record.data {
            let type_padded = format!("{:>width$}", "OPT", width = type_width);
            // Fill domain and TTL with spaces
            let fill_width = 1 + domain_width + 1 + ttl_width;
            let fill = " ".repeat(fill_width);
            // Data: " + udp_size ext_rcode version flags [options]"
            let opts_str = if options.is_empty() {
                "[]".to_string()
            } else {
                format!("[{}]", options.iter()
                    .map(|(code, data)| format!("{}: {:?}", code, data))
                    .collect::<Vec<_>>()
                    .join(", "))
            };
            println!("{}{} + {} {} {} {} {}", 
                type_padded, fill,
                udp_payload_size, extended_rcode, version, flags, opts_str);
        }
    }
}

fn colorize_type(type_str: &str) -> String {
    format!("\x1b[1;32m{}\x1b[0m", type_str)
}

pub fn type_name(type_num: u16) -> String {
    match type_num {
        1 => "A".to_string(),
        2 => "NS".to_string(),
        5 => "CNAME".to_string(),
        6 => "SOA".to_string(),
        12 => "PTR".to_string(),
        13 => "HINFO".to_string(),
        15 => "MX".to_string(),
        16 => "TXT".to_string(),
        28 => "AAAA".to_string(),
        29 => "LOC".to_string(),
        33 => "SRV".to_string(),
        35 => "NAPTR".to_string(),
        41 => "OPT".to_string(),
        44 => "SSHFP".to_string(),
        52 => "TLSA".to_string(),
        257 => "CAA".to_string(),
        _ => type_num.to_string(),
    }
}

pub fn class_name(class_num: u16) -> String {
    match class_num {
        1 => "IN".to_string(),
        3 => "CH".to_string(),
        4 => "HS".to_string(),
        _ => class_num.to_string(),
    }
}

pub fn format_ttl(ttl: u32, format_durations: bool) -> String {
    if !format_durations {
        return ttl.to_string();
    }

    if ttl == 0 {
        return "0s".to_string();
    }

    let mut remaining = ttl;
    let mut parts = Vec::new();

    let days = remaining / 86400;
    remaining %= 86400;
    let hours = remaining / 3600;
    remaining %= 3600;
    let minutes = remaining / 60;
    let seconds = remaining % 60;

    if days > 0 {
        parts.push(format!("{}d", days));
        parts.push(format!("{:02}h", hours));
        parts.push(format!("{:02}m", minutes));
        parts.push(format!("{:02}s", seconds));
    } else if hours > 0 {
        parts.push(format!("{}h", hours));
        parts.push(format!("{:02}m", minutes));
        parts.push(format!("{:02}s", seconds));
    } else if minutes > 0 {
        parts.push(format!("{}m", minutes));
        parts.push(format!("{:02}s", seconds));
    } else {
        parts.push(format!("{}s", seconds));
    }

    parts.join("")
}

fn format_record_data(data: &RecordData, format_durations: bool) -> String {
    match data {
        RecordData::A(ip) => ip.to_string(),
        RecordData::Aaaa(ip) => ip.to_string(),
        RecordData::Ns(name) => format!("\"{}\"", name),
        RecordData::Cname(name) => format!("\"{}\"", name),
        RecordData::Ptr(name) => format!("\"{}\"", name),
        RecordData::Mx { preference, exchange } => {
            format!("{} \"{}\"", preference, exchange)
        }
        RecordData::Txt(parts) => {
            parts.iter()
                .map(|p| format!("\"{}\"", escape_txt(p)))
                .collect::<Vec<_>>()
                .join(" ")
        }
        RecordData::Soa { mname, rname, serial, refresh, retry, expire, minimum } => {
            format!("\"{}\" \"{}\" {} {} {} {} {}",
                mname, rname, serial,
                format_ttl(*refresh, format_durations),
                format_ttl(*retry, format_durations),
                format_ttl(*expire, format_durations),
                format_ttl(*minimum, format_durations),
            )
        }
        RecordData::Srv { priority, weight, port, target } => {
            format!("{} {} \"{}\":{}", priority, weight, target, port)
        }
        RecordData::Caa { critical, tag, value } => {
            let critical_str = if *critical { "(critical)" } else { "(non-critical)" };
            format!("\"{}\" \"{}\" {}", tag, value, critical_str)
        }
        RecordData::Naptr { order, preference, flags, service, regexp, replacement } => {
            format!("{} {} \"{}\" \"{}\" \"{}\" \"{}\"",
                order, preference, flags, service, regexp, replacement)
        }
        RecordData::Sshfp { algorithm, fp_type, fingerprint } => {
            format!("{} {} {}", algorithm, fp_type, hex::encode(fingerprint))
        }
        RecordData::Tlsa { cert_usage, selector, matching_type, cert_data } => {
            format!("{} {} {} {}", cert_usage, selector, matching_type, hex::encode(cert_data))
        }
        RecordData::Hinfo { cpu, os } => {
            format!("\"{}\" \"{}\"", cpu, os)
        }
        RecordData::Opt { udp_payload_size, extended_rcode, version, flags, options } => {
            // Should not reach here in normal text output
            format!("+ {} {} {} {} []", udp_payload_size, extended_rcode, version, flags)
        }
        RecordData::Unknown { type_num, data } => {
            // Display as sequence of numbers
            data.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(" ")
        }
    }
}

fn escape_txt(data: &[u8]) -> String {
    String::from_utf8_lossy(data)
        .replace('\\', "\\\\")
        .replace('"', "\\\"")
}
