static mut LOG_LEVEL: LogLevel = LogLevel::Off;

macro_rules! log_info {
    ($module:expr, $($arg:tt)*) => {
        unsafe {
            if LOG_LEVEL >= LogLevel::Info {
                eprintln!("\x1b[38;5;243m[\x1b[0m\x1b[36mINFO\x1b[0m {}\x1b[38;5;243m]\x1b[0m {}", $module, format!($($arg)*));
