fn type_name_to_id(s: &str) -> Option<u16> {
    match s.to_ascii_uppercase().as_str() {
        "A" => Some(1), "NS" => Some(2), "CNAME" => Some(5), "SOA" => Some(6),
        "PTR" => Some(12), "HINFO" => Some(13), "MX" => Some(15), "TXT" => Some(16),
        "AAAA" => Some(28), "LOC" => Some(29), "SRV" => Some(33), "NAPTR" => Some(35),
        "OPT" => Some(41), "SSHFP" => Some(44), "TLSA" => Some(52), "CAA" => Some(257),
        "ANY" => Some(255), "AXFR" => Some(252), "IXFR" => Some(251),
        "AFSDB" => Some(18), "CERT" => Some(37), "DS" => Some(43),
        "RRSIG" => Some(46), "NSEC" => Some(47), "DNSKEY" => Some(48),
        "NSEC3" => Some(50), "NSEC3PARAM" => Some(51), "DNAME" => Some(39),
        "APL" => Some(42), "IPSECKEY" => Some(45), "DHCID" => Some(49),
        "HIP" => Some(55), "CDS" => Some(59), "CDNSKEY" => Some(60),
        "OPENPGPKEY" => Some(61), "CSYNC" => Some(62), "ZONEMD" => Some(63),
        "SVCB" => Some(64), "HTTPS" => Some(65),
        "TKEY" => Some(249), "TSIG" => Some(250), "URI" => Some(256),
