fn type_id_to_name(id: u16) -> String {
    match id {
        1 => "A", 2 => "NS", 5 => "CNAME", 6 => "SOA", 12 => "PTR", 13 => "HINFO",
        15 => "MX", 16 => "TXT", 28 => "AAAA", 29 => "LOC", 33 => "SRV", 35 => "NAPTR",
        41 => "OPT", 44 => "SSHFP", 52 => "TLSA", 255 => "ANY", 257 => "CAA",
        _ => return id.to_string(),
    }.to_string()
}

fn class_id_to_name(id: u16) -> String {
    match id { 1 => "IN", 3 => "CH", 4 => "HS", _ => return id.to_string() }.to_string()
}

fn get_system_nameservers() -> Result<Vec<(String, u16)>, String> {
    let content = std::fs::read_to_string("/etc/resolv.conf")
        .map_err(|e| format!("Failed to read /etc/resolv.conf: {}", e))?;
    let mut servers = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("nameserver") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 { servers.push((parts[1].to_string(), 53u16)); }
        }
    }
    if servers.is_empty() { Err("No nameservers found".to_string()) } else { Ok(servers) }
}

fn parse_nameserver(s: &str) -> (String, u16) {
    if let Some(idx) = s.rfind(':') {
        let host = &s[..idx];
        let port_str = &s[idx+1..];
        if let Ok(port) = port_str.parse::<u16>() {
            return (host.to_string(), port);
        }
    }
    (s.to_string(), 53)
}

fn parse_options(args: &[String]) -> Result<Options, String> {
    let mut domains: Vec<String> = Vec::new();
    let mut record_types: Vec<u16> = Vec::new();
    let mut classes: Vec<u16> = Vec::new();
    let mut nameservers: Vec<(String, u16)> = Vec::new();
    let mut transports: Vec<Transport> = Vec::new();
    let mut format = OutputFormat::Text;
    let mut color = ColorMode::Automatic;
    let mut measure_time = false;
    let mut format_durations = true;
    let mut edns = EdnsMode::Hide;
    let mut txid: Option<u16> = None;
    let mut tweaks = ProtocolTweaks::default();

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        match arg.as_str() {
            "--help" | "-?" => { print_help(); process::exit(0); }
            "--version" | "-v" => { print_version(); process::exit(0); }
            "-q" | "--query" => {
                i += 1;
                if i >= args.len() { return Err(format!("Option '{}' requires argument", arg)); }
                log_trace!("dog::options", "Got domain -> {:?}", args[i]);
                domains.push(args[i].clone());
            }
            "-t" | "--type" => {
                i += 1;
                if i >= args.len() { return Err(format!("Option '{}' requires argument", arg)); }
                let t = type_name_to_id(&args[i])
                    .ok_or_else(|| format!("Unknown type: {}", args[i]))?;
                record_types.push(t);
            }
            "-n" | "--nameserver" => {
                i += 1;
                if i >= args.len() { return Err(format!("Option '{}' requires argument", arg)); }
                nameservers.push(parse_nameserver(&args[i]));
            }
            "--class" => {
                i += 1;
                if i >= args.len() { return Err(format!("Option '--class' requires argument")); }
                let c = class_name_to_id(&args[i])
                    .ok_or_else(|| format!("Unknown class: {}", args[i]))?;
                classes.push(c);
            }
            "--edns" => {
                i += 1;
                if i >= args.len() { return Err("Option '--edns' requires argument".to_string()); }
                edns = match args[i].to_ascii_lowercase().as_str() {
                    "disable" => EdnsMode::Disable,
                    "show" => EdnsMode::Show,
                    "hide" => EdnsMode::Hide,
                    _ => return Err(format!("Unknown edns setting: {}", args[i])),
                };
            }
            "--txid" => {
                i += 1;
                if i >= args.len() { return Err("Option '--txid' requires argument".to_string()); }
                txid = Some(args[i].parse::<u16>().map_err(|_| format!("Invalid txid: {}", args[i]))?);
            }
            "-U" | "--udp" => transports.push(Transport::Udp),
            "-T" | "--tcp" => transports.push(Transport::Tcp),
            "-S" | "--tls" => transports.push(Transport::Tls),
            "-H" | "--https" => transports.push(Transport::Https),
            "-1" | "--short" => format = OutputFormat::Short,
            "-J" | "--json" => format = OutputFormat::Json,
            "--seconds" => format_durations = false,
            "--time" => measure_time = true,
            "--" => {
                // Rest are free args
                for j in (i+1)..args.len() {
                    log_trace!("dog::options", "Got domain -> {:?}", args[j]);
                    domains.push(args[j].clone());
                }
                break;
            }
            s if s.starts_with("--colour=") || s.starts_with("--color=") => {
                let val = s.splitn(2, '=').nth(1).unwrap_or("");
                color = match val.to_ascii_lowercase().as_str() {
                    "always" => ColorMode::Always,
                    "never" => ColorMode::Never,
                    _ => ColorMode::Automatic,
                };
            }
            s if s.starts_with("--colour") || s.starts_with("--color") => {
                // --colour VALUE form
                i += 1;
                if i >= args.len() { return Err("Option '--colour' requires argument".to_string()); }
                color = match args[i].to_ascii_lowercase().as_str() {
                    "always" => ColorMode::Always,
                    "never" => ColorMode::Never,
                    _ => ColorMode::Automatic,
                };
            }
            s if s.starts_with("--edns=") => {
                let val = s[7..].to_ascii_lowercase();
                edns = match val.as_str() {
                    "disable" => EdnsMode::Disable,
                    "show" => EdnsMode::Show,
                    _ => EdnsMode::Hide,
                };
            }
            s if s.starts_with("--txid=") => {
                txid = Some(s[7..].parse::<u16>().map_err(|_| format!("Invalid txid: {}", &s[7..]))?);
            }
            s if s.starts_with("--query=") => {
                let domain = s[8..].to_string();
                log_trace!("dog::options", "Got domain -> {:?}", domain);
                domains.push(domain);
            }
            s if s.starts_with("--type=") => {
                let t = type_name_to_id(&s[7..])
                    .ok_or_else(|| format!("Unknown type: {}", &s[7..]))?;
                record_types.push(t);
            }
            s if s.starts_with("--nameserver=") => {
                nameservers.push(parse_nameserver(&s[13..]));
            }
            s if s.starts_with("--class=") => {
                let c = class_name_to_id(&s[8..])
                    .ok_or_else(|| format!("Unknown class: {}", &s[8..]))?;
                classes.push(c);
            }
            s if s.starts_with("-Z=") || s.starts_with("-Z") && s.len() > 2 => {
                let val = if s.starts_with("-Z=") { &s[3..] } else { &s[2..] };
                match val {
                    "aa" => tweaks.set_aa = true,
                    "ad" => tweaks.set_ad = true,
                    "cd" => tweaks.set_cd = true,
                    v if v.starts_with("bufsize=") => {
                        if let Ok(sz) = v[8..].parse::<u16>() { tweaks.udp_payload_size = Some(sz); }
                    }
                    _ => {}
                }
            }
            s if s.starts_with('-') => {
                return Err(format!("Unrecognized option: '{}'", &s[1..]));
            }
            s if s.starts_with('@') => {
                nameservers.push(parse_nameserver(&s[1..]));
            }
            s => {
                if let Some(tid) = type_name_to_id(s) {
                    record_types.push(tid);
                } else if let Some(cid) = class_name_to_id(s) {
                    classes.push(cid);
                } else {
                    log_trace!("dog::options", "Got domain -> {:?}", s);
                    domains.push(s.to_string());
                }
            }
        }
        i += 1;
    }

    if record_types.is_empty() { record_types.push(1); } // A
    if classes.is_empty() { classes.push(1); } // IN
    if transports.is_empty() { transports.push(Transport::Automatic); }

    if domains.is_empty() {
        print_help();
        process::exit(3);
    }

    if nameservers.is_empty() {
        nameservers = get_system_nameservers()
            .map_err(|e| format!("Failed to get system nameservers: {}", e))?;
    }

    Ok(Options { domains, record_types, classes, nameservers, transports,
        format, color, measure_time, format_durations, edns, txid, tweaks })
}

fn print_help() {
    println!("dog \u{25CF} command-line DNS client");
    println!();
    println!("Usage:");
    println!("  dog [OPTIONS] [--] <arguments>");
    println!();
    println!("Examples:");
    println!("  dog example.net                          Query a domain using default settings");
    println!("  dog example.net MX                       ...looking up MX records instead");
    println!("  dog example.net MX @1.1.1.1              ...using a specific nameserver instead");
    println!("  dog example.net MX @1.1.1.1 -T           ...using TCP rather than UDP");
    println!("  dog -q example.net -t MX -n 1.1.1.1 -T   As above, but using explicit arguments");
    println!();
    println!("Query options:");
    println!("  <arguments>              Human-readable host names, nameservers, types, or classes");
    println!("  -q, --query=HOST         Host name or domain name to query");
    println!("  -t, --type=TYPE          Type of the DNS record being queried (A, MX, NS...)");
    println!("  -n, --nameserver=ADDR    Address of the nameserver to send packets to");
    println!("  --class=CLASS            Network class of the DNS record being queried (IN, CH, HS)");
    println!();
