// DNS structures
#[derive(Debug, Clone, Copy, PartialEq)]
enum Section { Answer, Authority, Additional }

#[derive(Debug, Clone)]
enum RecordData {
    A(Ipv4Addr),
    Aaaa(Ipv6Addr),
    Ns(String),
    Cname(String),
    Ptr(String),
    Mx { preference: u16, exchange: String },
    Txt(Vec<Vec<u8>>),
    Soa { mname: String, rname: String, serial: u32, refresh: u32, retry: u32, expire: u32, minimum: u32 },
    Srv { priority: u16, weight: u16, port: u16, target: String },
    Caa { critical: bool, tag: String, value: String },
    Naptr { order: u16, preference: u16, flags: String, service: String, regexp: String, replacement: String },
    Opt { udp_payload_size: u16, extended_rcode: u8, version: u8, flags: u16, options: Vec<(u16, Vec<u8>)> },
    Sshfp { algorithm: u8, fp_type: u8, fingerprint: Vec<u8> },
    Tlsa { cert_usage: u8, selector: u8, matching_type: u8, cert_data: Vec<u8> },
    Hinfo { cpu: String, os: String },
    Unknown { type_num: u16, data: Vec<u8> },
}

#[derive(Debug, Clone)]
struct Record {
    name: String,
    rtype: u16,
    class: u16,
    ttl: u32,
    data: RecordData,
    section: Section,
}

#[derive(Debug)]
struct DnsResponse {
    query_name: String,
    query_type: u16,
    query_class: u16,
    answers: Vec<Record>,
    authorities: Vec<Record>,
    additionals: Vec<Record>,
    rcode: u8,
    elapsed: Duration,
}

fn random_u16() -> u16 {
    use std::fs::File;
    let mut f = File::open("/dev/urandom").unwrap();
    let mut buf = [0u8; 2];
    f.read_exact(&mut buf).unwrap();
    u16::from_le_bytes(buf)
}

fn encode_domain_name(buf: &mut Vec<u8>, name: &str) {
    let name = name.trim_end_matches('.');
    if name.is_empty() { buf.push(0); return; }
    for label in name.split('.') {
        let bytes = label.as_bytes();
        buf.push(bytes.len() as u8);
        buf.extend_from_slice(bytes);
    }
    buf.push(0);
}

fn build_request(domain: &str, qtype: u16, qclass: u16, opts: &Options) -> Vec<u8> {
    let mut buf = Vec::new();
    let txid = opts.txid.unwrap_or_else(random_u16);
    buf.push((txid >> 8) as u8);
    buf.push((txid & 0xff) as u8);
    let mut flags: u16 = 0x0100;
    if opts.tweaks.set_aa { flags |= 0x0400; }
    if opts.tweaks.set_ad { flags |= 0x0020; }
    if opts.tweaks.set_cd { flags |= 0x0010; }
    buf.push((flags >> 8) as u8);
    buf.push((flags & 0xff) as u8);
    buf.push(0); buf.push(1); // QDCOUNT
    buf.push(0); buf.push(0); // ANCOUNT
    buf.push(0); buf.push(0); // NSCOUNT
    let has_opt = opts.edns != EdnsMode::Disable;
    buf.push(0); buf.push(if has_opt { 1 } else { 0 }); // ARCOUNT
    encode_domain_name(&mut buf, domain);
    buf.push((qtype >> 8) as u8); buf.push((qtype & 0xff) as u8);
    buf.push((qclass >> 8) as u8); buf.push((qclass & 0xff) as u8);
    if has_opt {
        buf.push(0); // root name
        buf.push(0); buf.push(41); // OPT type
        let udp_size = opts.tweaks.udp_payload_size.unwrap_or(4096);
        buf.push((udp_size >> 8) as u8); buf.push((udp_size & 0xff) as u8);
        buf.push(0); buf.push(0); buf.push(0); buf.push(0); // TTL (ext rcode, version, flags)
        buf.push(0); buf.push(0); // RDLENGTH = 0
    }
    buf
}

fn read_u16_be(data: &[u8], pos: &mut usize) -> u16 {
    let v = ((data[*pos] as u16) << 8) | (data[*pos+1] as u16);
    *pos += 2; v
}
fn read_u32_be(data: &[u8], pos: &mut usize) -> u32 {
    let v = ((data[*pos] as u32) << 24) | ((data[*pos+1] as u32) << 16)
        | ((data[*pos+2] as u32) << 8) | (data[*pos+3] as u32);
    *pos += 4; v
}
fn at_u16(data: &[u8], pos: usize) -> u16 {
    ((data[pos] as u16) << 8) | (data[pos+1] as u16)
}
fn at_u32(data: &[u8], pos: usize) -> u32 {
    ((data[pos] as u32) << 24) | ((data[pos+1] as u32) << 16)
        | ((data[pos+2] as u32) << 8) | (data[pos+3] as u32)
}

fn read_name(data: &[u8], start: usize) -> Result<(String, usize), String> {
    let mut parts: Vec<String> = Vec::new();
    let mut pos = start;
    let mut end_pos: Option<usize> = None;
    let mut jumps = 0;
    loop {
        if pos >= data.len() { return Err("Name truncated".to_string()); }
        let b = data[pos];
        if b == 0 { pos += 1; break; }
        if (b & 0xc0) == 0xc0 {
            if pos + 1 >= data.len() { return Err("Bad pointer".to_string()); }
            let ptr = ((b & 0x3f) as usize) << 8 | data[pos+1] as usize;
            if end_pos.is_none() { end_pos = Some(pos + 2); }
            pos = ptr;
            jumps += 1;
            if jumps > 20 { return Err("Too many pointer jumps".to_string()); }
        } else {
            let len = b as usize;
            pos += 1;
            if pos + len > data.len() { return Err("Label truncated".to_string()); }
            parts.push(String::from_utf8_lossy(&data[pos..pos+len]).to_string());
            pos += len;
        }
    }
    if end_pos.is_none() { end_pos = Some(pos); }
    let name = if parts.is_empty() { ".".to_string() } else { format!("{}.", parts.join(".")) };
    Ok((name, end_pos.unwrap()))
}

fn read_char_string(data: &[u8], pos: &mut usize) -> Vec<u8> {
    if *pos >= data.len() { return Vec::new(); }
    let len = data[*pos] as usize; *pos += 1;
    if *pos + len <= data.len() {
        let r = data[*pos..*pos+len].to_vec(); *pos += len; r
    } else { Vec::new() }
}

fn parse_record(data: &[u8], pos: usize, section: Section) -> Result<(Record, usize), String> {
    let mut pos = pos;
    let (name, new_pos) = read_name(data, pos)?;
    pos = new_pos;
    if pos + 4 > data.len() { return Err("Record truncated".to_string()); }
    let rtype = read_u16_be(data, &mut pos);
    if rtype == 41 {
        // OPT record
        let udp_payload_size = read_u16_be(data, &mut pos);
        let extended_rcode = data[pos]; let version = data[pos+1];
        let flags = at_u16(data, pos+2); pos += 4;
        let rdlen = read_u16_be(data, &mut pos) as usize;
        let rdata_end = pos + rdlen;
        let mut options = Vec::new();
        while pos + 4 <= rdata_end {
            let code = read_u16_be(data, &mut pos);
            let olen = read_u16_be(data, &mut pos) as usize;
            if pos + olen <= rdata_end {
                options.push((code, data[pos..pos+olen].to_vec())); pos += olen;
            } else { break; }
        }
        pos = rdata_end;
        return Ok((Record { name, rtype, class: udp_payload_size, ttl: 0,
            data: RecordData::Opt { udp_payload_size, extended_rcode, version, flags, options },
            section }, pos));
    }
    let class = read_u16_be(data, &mut pos);
    let ttl = read_u32_be(data, &mut pos);
    let rdlen = read_u16_be(data, &mut pos) as usize;
    if pos + rdlen > data.len() { return Err("RData truncated".to_string()); }
    let rdata = &data[pos..pos+rdlen];
    let rdata_abs = pos;
    let record_data = match rtype {
        1 => { // A
            if rdlen != 4 { return Err("Bad A".to_string()); }
            RecordData::A(Ipv4Addr::new(rdata[0], rdata[1], rdata[2], rdata[3]))
        }
        28 => { // AAAA
            if rdlen != 16 { return Err("Bad AAAA".to_string()); }
            let mut b = [0u8;16]; b.copy_from_slice(rdata);
            RecordData::Aaaa(Ipv6Addr::from(b))
        }
        2 => { let (n, _) = read_name(data, rdata_abs)?; RecordData::Ns(n) }
        5 => { let (n, _) = read_name(data, rdata_abs)?; RecordData::Cname(n) }
        12 => { let (n, _) = read_name(data, rdata_abs)?; RecordData::Ptr(n) }
        15 => {
            let pref = at_u16(rdata, 0);
            let (exch, _) = if rdlen > 2 { read_name(data, rdata_abs+2)? } else { ("".to_string(), 0) };
            RecordData::Mx { preference: pref, exchange: exch }
        }
        16 => {
            let mut parts = Vec::new(); let mut i = 0;
            while i < rdlen {
                let l = rdata[i] as usize; i += 1;
                if i + l <= rdlen { parts.push(rdata[i..i+l].to_vec()); i += l; } else { break; }
            }
            RecordData::Txt(parts)
        }
        6 => {
            let (mname, np) = read_name(data, rdata_abs)?;
            let (rname, np2) = read_name(data, np)?;
            let off = np2 - rdata_abs;
            if off + 20 <= rdlen {
                let serial = at_u32(rdata, off);
                let refresh = at_u32(rdata, off+4);
                let retry = at_u32(rdata, off+8);
                let expire = at_u32(rdata, off+12);
                let minimum = at_u32(rdata, off+16);
                RecordData::Soa { mname, rname, serial, refresh, retry, expire, minimum }
            } else {
                RecordData::Soa { mname, rname, serial:0, refresh:0, retry:0, expire:0, minimum:0 }
            }
        }
        33 => {
            if rdlen < 6 { return Err("Bad SRV".to_string()); }
            let priority = at_u16(rdata, 0); let weight = at_u16(rdata, 2); let port = at_u16(rdata, 4);
            let (target, _) = read_name(data, rdata_abs+6)?;
            RecordData::Srv { priority, weight, port, target }
        }
        257 => {
            if rdlen < 2 { return Err("Bad CAA".to_string()); }
            let flags = rdata[0]; let critical = (flags & 0x80) != 0;
            let tag_len = rdata[1] as usize;
            if 2 + tag_len > rdlen { return Err("Bad CAA tag".to_string()); }
            let tag = String::from_utf8_lossy(&rdata[2..2+tag_len]).to_string();
            let value = String::from_utf8_lossy(&rdata[2+tag_len..]).to_string();
            RecordData::Caa { critical, tag, value }
        }
        35 => {
            if rdlen < 4 { return Err("Bad NAPTR".to_string()); }
            let order = at_u16(rdata, 0); let preference = at_u16(rdata, 2);
            let mut i = 4;
            let flags_b = read_char_string(rdata, &mut i);
            let service_b = read_char_string(rdata, &mut i);
            let regexp_b = read_char_string(rdata, &mut i);
            let (replacement, _) = read_name(data, rdata_abs + i)?;
            RecordData::Naptr {
                order, preference,
                flags: String::from_utf8_lossy(&flags_b).to_string(),
                service: String::from_utf8_lossy(&service_b).to_string(),
                regexp: String::from_utf8_lossy(&regexp_b).to_string(),
                replacement,
            }
        }
        44 => {
            if rdlen < 2 { return Err("Bad SSHFP".to_string()); }
            RecordData::Sshfp { algorithm: rdata[0], fp_type: rdata[1], fingerprint: rdata[2..].to_vec() }
        }
        52 => {
            if rdlen < 3 { return Err("Bad TLSA".to_string()); }
            RecordData::Tlsa { cert_usage: rdata[0], selector: rdata[1], matching_type: rdata[2], cert_data: rdata[3..].to_vec() }
        }
        13 => {
            let mut i = 0;
            let cpu_b = read_char_string(rdata, &mut i);
            let os_b = read_char_string(rdata, &mut i);
            RecordData::Hinfo { cpu: String::from_utf8_lossy(&cpu_b).to_string(), os: String::from_utf8_lossy(&os_b).to_string() }
        }
        _ => RecordData::Unknown { type_num: rtype, data: rdata.to_vec() },
    };
    pos += rdlen;
    Ok((Record { name, rtype, class, ttl, data: record_data, section }, pos))
}

fn parse_response(data: &[u8], elapsed: Duration) -> Result<DnsResponse, String> {
    log_info!("dns::wire", "Parsing response");
    log_trace!("dns::wire", "Bytes -> {:?}", data);
    if data.len() < 12 { return Err("Response too short".to_string()); }
    let mut pos = 0;
    let _txid = read_u16_be(data, &mut pos);
    let flags = read_u16_be(data, &mut pos);
    let qdcount = read_u16_be(data, &mut pos) as usize;
    let ancount = read_u16_be(data, &mut pos) as usize;
    let nscount = read_u16_be(data, &mut pos) as usize;
    let arcount = read_u16_be(data, &mut pos) as usize;
    let rcode = (flags & 0x000f) as u8;
    let mut query_name = String::new();
    let mut query_type = 0u16;
    let mut query_class = 0u16;
    for _ in 0..qdcount {
        let (n, np) = read_name(data, pos)?; pos = np;
        query_name = n;
        query_type = read_u16_be(data, &mut pos);
        query_class = read_u16_be(data, &mut pos);
    }
    let mut answers = Vec::new();
    for _ in 0..ancount {
        let (r, np) = parse_record(data, pos, Section::Answer)?; pos = np; answers.push(r);
    }
    let mut authorities = Vec::new();
    for _ in 0..nscount {
        let (r, np) = parse_record(data, pos, Section::Authority)?; pos = np; authorities.push(r);
    }
    let mut additionals = Vec::new();
    for _ in 0..arcount {
        let (r, np) = parse_record(data, pos, Section::Additional)?; pos = np; additionals.push(r);
    }
    Ok(DnsResponse { query_name, query_type, query_class, answers, authorities, additionals, rcode, elapsed })
}

fn send_udp(data: &[u8], host: &str, port: u16) -> Result<Vec<u8>, String> {
    log_info!("dns_transport::udp", "Opening UDP socket");
    let socket = UdpSocket::bind("0.0.0.0:0").map_err(|e| e.to_string())?;
    log_debug!("dns_transport::udp", "Opened");
    let addr = format!("{}:{}", host, port);
    log_info!("dns_transport::udp", "Sending {} bytes of data to {} over UDP", data.len(), addr);
    socket.send_to(data, &addr).map_err(|e| e.to_string())?;
    log_debug!("dns_transport::udp", "Wrote {} bytes", data.len());
    socket.set_read_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
    log_info!("dns_transport::udp", "Waiting to receive...");
    let mut buf = vec![0u8; 65535];
    let (len, _) = socket.recv_from(&mut buf).map_err(|e| e.to_string())?;
    log_info!("dns_transport::udp", "Received {} bytes of data", len);
    buf.truncate(len);
    Ok(buf)
}

fn send_tcp(data: &[u8], host: &str, port: u16) -> Result<Vec<u8>, String> {
    let addr = format!("{}:{}", host, port);
    let mut stream = TcpStream::connect(&addr).map_err(|e| e.to_string())?;
    stream.set_read_timeout(Some(Duration::from_secs(5))).map_err(|e| e.to_string())?;
    let len = data.len() as u16;
    stream.write_all(&len.to_be_bytes()).map_err(|e| e.to_string())?;
    stream.write_all(data).map_err(|e| e.to_string())?;
    let mut lbuf = [0u8; 2];
    stream.read_exact(&mut lbuf).map_err(|e| e.to_string())?;
    let rlen = u16::from_be_bytes(lbuf) as usize;
    let mut buf = vec![0u8; rlen];
    stream.read_exact(&mut buf).map_err(|e| e.to_string())?;
    Ok(buf)
}

fn perform_query(domain: &str, qtype: u16, qclass: u16, ns: &str, port: u16, transport: Transport, opts: &Options) -> Result<DnsResponse, String> {
    let req = build_request(domain, qtype, qclass, opts);
    let start = Instant::now();
    let resp_bytes = match transport {
        Transport::Udp => send_udp(&req, ns, port)?,
        Transport::Tcp => send_tcp(&req, ns, port)?,
        Transport::Automatic => {
            let bytes = send_udp(&req, ns, port)?;
            // TODO: retry with TCP if truncated
            bytes
        }
        Transport::Tls => return Err("TLS not supported".to_string()),
        Transport::Https => return Err("HTTPS not supported".to_string()),
    };
    let elapsed = start.elapsed();
    parse_response(&resp_bytes, elapsed)
}

fn format_ttl(ttl: u32, fmt: bool) -> String {
    if !fmt { return ttl.to_string(); }
    if ttl == 0 { return "0s".to_string(); }
    let days = ttl / 86400;
    let rem = ttl % 86400;
    let hours = rem / 3600;
    let rem = rem % 3600;
    let mins = rem / 60;
    let secs = rem % 60;
    if days > 0 {
        format!("{}d{:02}h{:02}m{:02}s", days, hours, mins, secs)
    } else if hours > 0 {
        format!("{}h{:02}m{:02}s", hours, mins, secs)
    } else if mins > 0 {
        format!("{}m{:02}s", mins, secs)
    } else {
        format!("{}s", secs)
    }
}

fn format_data(d: &RecordData, fmt: bool) -> String {
    match d {
        RecordData::A(ip) => ip.to_string(),
        RecordData::Aaaa(ip) => ip.to_string(),
        RecordData::Ns(n) => format!("\"{}\"", n),
        RecordData::Cname(n) => format!("\"{}\"", n),
        RecordData::Ptr(n) => format!("\"{}\"", n),
        RecordData::Mx { preference, exchange } => format!("{} \"{}\"", preference, exchange),
        RecordData::Txt(parts) => parts.iter().map(|p| format!("\"{}\"", String::from_utf8_lossy(p))).collect::<Vec<_>>().join(" "),
        RecordData::Soa { mname, rname, serial, refresh, retry, expire, minimum } => {
            format!("\"{}\" \"{}\" {} {} {} {} {}", mname, rname, serial,
                format_ttl(*refresh, fmt), format_ttl(*retry, fmt),
                format_ttl(*expire, fmt), format_ttl(*minimum, fmt))
        }
        RecordData::Srv { priority, weight, port, target } => format!("{} {} \"{}\":{}", priority, weight, target, port),
        RecordData::Caa { critical, tag, value } => {
            format!("\"{}\" \"{}\" {}", tag, value, if *critical { "(critical)" } else { "(non-critical)" })
        }
        RecordData::Naptr { order, preference, flags, service, regexp, replacement } => {
            format!("{} {} \"{}\" \"{}\" \"{}\" \"{}\"", order, preference, flags, service, regexp, replacement)
        }
        RecordData::Sshfp { algorithm, fp_type, fingerprint } => {
            format!("{} {} {}", algorithm, fp_type, hex_encode(fingerprint))
        }
        RecordData::Tlsa { cert_usage, selector, matching_type, cert_data } => {
            format!("{} {} {} {}", cert_usage, selector, matching_type, hex_encode(cert_data))
        }
        RecordData::Hinfo { cpu, os } => format!("\"{}\" \"{}\"", cpu, os),
        RecordData::Opt { .. } => String::new(),
        RecordData::Unknown { data, .. } => data.iter().map(|b| b.to_string()).collect::<Vec<_>>().join(" "),
    }
}

fn hex_encode(data: &[u8]) -> String {
    data.iter().map(|b| format!("{:02x}", b)).collect()
}

fn data_to_json(d: &RecordData) -> String {
    match d {
        RecordData::A(ip) => format!("{{\"address\":{}}}", json_str(&ip.to_string())),
        RecordData::Aaaa(ip) => format!("{{\"address\":{}}}", json_str(&ip.to_string())),
        RecordData::Ns(n) => format!("{{\"nameserver\":{}}}", json_str(n)),
        RecordData::Cname(n) => format!("{{\"domain\":{}}}", json_str(n)),
        RecordData::Ptr(n) => format!("{{\"cname\":{}}}", json_str(n)),
        RecordData::Mx { preference, exchange } => format!("{{\"preference\":{},\"exchange\":{}}}", preference, json_str(exchange)),
        RecordData::Txt(parts) => {
            let msgs: Vec<String> = parts.iter().map(|p| json_str(&String::from_utf8_lossy(p))).collect();
            format!("{{\"messages\":[{}]}}", msgs.join(","))
        }
        RecordData::Soa { mname, .. } => format!("{{\"mname\":{}}}", json_str(mname)),
        RecordData::Srv { priority, weight, port, target } => {
            format!("{{\"priority\":{},\"weight\":{},\"port\":{},\"target\":{}}}", priority, weight, port, json_str(target))
        }
        RecordData::Caa { critical, tag, value } => {
            format!("{{\"critical\":{},\"tag\":{},\"value\":{}}}", critical, json_str(tag), json_str(value))
        }
        RecordData::Naptr { order, flags, service, regexp, replacement, .. } => {
            format!("{{\"order\":{},\"flags\":{},\"service\":{},\"regex\":{},\"replacement\":{}}}",
                order, json_str(flags), json_str(service), json_str(regexp), json_str(replacement))
        }
        RecordData::Sshfp { algorithm, fp_type, fingerprint } => {
            format!("{{\"algorithm\":{},\"fp_type\":{},\"fingerprint\":{}}}", algorithm, fp_type, json_str(&hex_encode(fingerprint)))
        }
        RecordData::Tlsa { cert_usage, selector, matching_type, cert_data } => {
            format!("{{\"cert_usage\":{},\"selector\":{},\"matching_type\":{},\"cert_data\":{}}}", cert_usage, selector, matching_type, json_str(&hex_encode(cert_data)))
        }
        RecordData::Hinfo { cpu, os } => format!("{{\"cpu\":{},\"os\":{}}}", json_str(cpu), json_str(os)),
        RecordData::Opt { version, options, .. } => {
            let opts_arr: Vec<String> = options.iter().map(|(c, d)| format!("{{\"code\":{},\"data\":{:?}}}", c, d)).collect();
            format!("{{\"version\":{},\"data\":[{}]}}", version, opts_arr.join(","))
        }
        RecordData::Unknown { type_num, data } => {
            format!("{{\"type\":{},\"data\":{:?}}}", type_num, data)
        }
    }
}

fn json_str(s: &str) -> String {
    let mut result = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 32 => result.push_str(&format!("\\u{:04x}", c as u32)),
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

fn record_to_json(r: &Record) -> String {
    if r.rtype == 41 {
        return format!("{{\"name\":{},\"type\":\"OPT\",\"data\":{}}}", json_str(&r.name), data_to_json(&r.data));
    }
    format!("{{\"name\":{},\"class\":{},\"ttl\":{},\"type\":{},\"data\":{}}}",
        json_str(&fqdn(&r.name)), json_str(&class_id_to_name(r.class)), r.ttl,
        json_str(&type_id_to_name(r.rtype)), data_to_json(&r.data))
}

fn fqdn(s: &str) -> String {
    if s.ends_with('.') { s.to_string() } else { format!("{}.", s) }
}

fn format_json_response(resp: &DnsResponse, include_time: bool) -> String {
    let queries = format!("[{{\"name\":{},\"class\":{},\"type\":{}}}]",
        json_str(&fqdn(&resp.query_name)), json_str(&class_id_to_name(resp.query_class)),
        json_str(&type_id_to_name(resp.query_type)));

    let answers: Vec<String> = resp.answers.iter().map(record_to_json).collect();
    let authorities: Vec<String> = resp.authorities.iter().map(record_to_json).collect();
    let additionals: Vec<String> = resp.additionals.iter().map(record_to_json).collect();

    format!("{{\"queries\":{},\"answers\":[{}],\"authorities\":[{}],\"additionals\":[{}]}}",
        queries, answers.join(","), authorities.join(","), additionals.join(","))
}

fn execute(opts: Options) -> i32 {
    let use_color = match opts.color {
        ColorMode::Always => true,
        ColorMode::Never => false,
        ColorMode::Automatic => io::stdout().is_terminal(),
    };

    let mut responses: Vec<DnsResponse> = Vec::new();
    let mut had_network_error = false;

    for domain in &opts.domains {
        for &qtype in &opts.record_types {
            for &qclass in &opts.classes {
                for (ns, port) in &opts.nameservers {
                    for &transport in &opts.transports {
                        match perform_query(domain, qtype, qclass, ns, *port, transport, &opts) {
                            Ok(resp) => responses.push(resp),
                            Err(e) => {
                                eprintln!("Error [network]: {}", e);
                                had_network_error = true;
                            }
                        }
                    }
                }
            }
        }
    }

    if had_network_error && responses.is_empty() { return 1; }

    match opts.format {
        OutputFormat::Json => {
            let resp_strs: Vec<String> = responses.iter().map(|r| format_json_response(r, false)).collect();
            let mut output = format!("{{\"responses\":[{}]}}", resp_strs.join(","));
            if opts.measure_time {
                if let Some(last) = responses.last() {
                    let secs = last.elapsed.as_secs();
                    let millis = last.elapsed.subsec_millis();
                    // Insert duration before closing }
                    output = format!("{{\"responses\":[{}],\"duration\":{{\"secs\":{},\"millis\":{}}}}}",
                        resp_strs.join(","), secs, millis);
                }
            }
            println!("{}", output);
        }
        OutputFormat::Short => {
            let mut found = false;
            for resp in &responses {
                for ans in &resp.answers {
                    if ans.rtype != 41 {
                        println!("{}", short_data(&ans.data));
                        found = true;
                    }
                }
            }
            if !found {
                eprintln!("No results");
                return 2;
            }
        }
        OutputFormat::Text => {
            print_text_responses(&responses, use_color, opts.format_durations, opts.measure_time, &opts);
        }
    }

    if had_network_error { 1 } else { 0 }
}

fn short_data(d: &RecordData) -> String {
    match d {
        RecordData::A(ip) => ip.to_string(),
        RecordData::Aaaa(ip) => ip.to_string(),
        RecordData::Ns(n) | RecordData::Cname(n) | RecordData::Ptr(n) => n.clone(),
        RecordData::Mx { exchange, .. } => exchange.clone(),
        RecordData::Txt(parts) => parts.iter().map(|p| String::from_utf8_lossy(p).to_string()).collect::<Vec<_>>().join(""),
        RecordData::Soa { mname, .. } => mname.clone(),
        RecordData::Srv { target, port, .. } => format!("{}:{}", target, port),
        RecordData::Caa { value, .. } => value.clone(),
        RecordData::Naptr { replacement, .. } => replacement.clone(),
        _ => String::new(),
    }
}

fn print_text_responses(responses: &[DnsResponse], use_color: bool, fmt_dur: bool, show_time: bool, opts: &Options) {
    let mut last_elapsed = Duration::from_millis(0);

    // Collect ALL records across all responses to determine column widths
    // BUT only do this per-response to match the original behavior
    // Actually looking at the output, multi-domain queries align all records together
    // Let me check: when querying example.net google.com A, the alignment spans both

    // Gather all visible records (non-OPT) to compute widths
    struct RowInfo {
        type_str: String,
        name: String,
        ttl_str: String,
        section: Section,
        data_str: String,
        is_opt: bool,
        opt_data: Option<RecordData>,
    }

    let show_opt = opts.edns == EdnsMode::Show;

    // We need to collect all rows first, then compute widths, then print
    let mut all_rows: Vec<RowInfo> = Vec::new();
    let mut all_rcodes: Vec<(u8, usize)> = Vec::new(); // (rcode, row_index_before)

    for resp in responses {
        if resp.rcode != 0 {
            all_rcodes.push((resp.rcode, all_rows.len()));
        }

        for r in resp.answers.iter().chain(resp.authorities.iter()) {
            all_rows.push(RowInfo {
                type_str: type_id_to_name(r.rtype),
                name: r.name.clone(),
                ttl_str: format_ttl(r.ttl, fmt_dur),
                section: r.section,
                data_str: format_data(&r.data, fmt_dur),
                is_opt: false,
                opt_data: None,
            });
        }

        if show_opt {
            for r in resp.additionals.iter() {
                if r.rtype == 41 {
                    all_rows.push(RowInfo {
                        type_str: "OPT".to_string(),
                        name: String::new(),
                        ttl_str: String::new(),
                        section: Section::Additional,
                        data_str: String::new(),
                        is_opt: true,
                        opt_data: Some(r.data.clone()),
                    });
                }
            }
        }

        last_elapsed = resp.elapsed;
    }

    // Compute column widths
    let type_width = all_rows.iter().map(|r| r.type_str.len()).max().unwrap_or(0);
    let name_width = all_rows.iter().filter(|r| !r.is_opt).map(|r| r.name.len()).max().unwrap_or(0);
    let ttl_width = all_rows.iter().filter(|r| !r.is_opt).map(|r| r.ttl_str.len()).max().unwrap_or(0);

    // Print
    let mut row_idx = 0;
    for resp in responses {
        // Print status if non-zero rcode
        if resp.rcode != 0 {
            let rcode_str = match resp.rcode {
                1 => "FormErr", 2 => "ServFail", 3 => "NXDomain",
                4 => "NotImp", 5 => "Refused", 6 => "YXDomain",
                7 => "YXRRSet", 8 => "NXRRSet", 9 => "NotAuth",
                10 => "NotZone", _ => "Unknown",
            };
            if use_color {
                println!("Status: \x1b[1;31m{}\x1b[0m", rcode_str);
            } else {
                println!("Status: {}", rcode_str);
            }
        }

        let resp_rows_start = row_idx;
        let resp_row_count = resp.answers.len() + resp.authorities.len()
            + if show_opt { resp.additionals.iter().filter(|r| r.rtype == 41).count() } else { 0 };

        for r in resp.answers.iter().chain(resp.authorities.iter()) {
            let type_str = type_id_to_name(r.rtype);
            let ttl_str = format_ttl(r.ttl, fmt_dur);
            let data_str = format_data(&r.data, fmt_dur);
            let section_marker = match r.section {
                Section::Answer | Section::Additional => "   ",
                Section::Authority => " A ",
            };

            if use_color {
                let type_pad = " ".repeat(type_width.saturating_sub(type_str.len()));
                let name_pad = " ".repeat(name_width.saturating_sub(r.name.len()));
                let ttl_pad = " ".repeat(ttl_width.saturating_sub(ttl_str.len()));
                print!("{}\x1b[1;32m{}\x1b[0m \x1b[1;34m{}\x1b[0m{} {}{}{}{}",
                    type_pad, type_str, r.name, name_pad, ttl_pad, ttl_str, section_marker, data_str);
                println!();
            } else {
                let type_padded = format!("{:>width$}", type_str, width = type_width);
                let name_padded = format!("{:<width$}", r.name, width = name_width);
                let ttl_padded = format!("{:>width$}", ttl_str, width = ttl_width);
                println!("{} {} {}{}{}", type_padded, name_padded, ttl_padded, section_marker, data_str);
            }
            row_idx += 1;
        }

        if show_opt {
            for r in resp.additionals.iter() {
                if r.rtype == 41 {
                    if let RecordData::Opt { udp_payload_size, extended_rcode, version, flags, options } = &r.data {
                        let type_padded = format!("{:>width$}", "OPT", width = type_width);
                        let fill_len = 1 + name_width + 1 + ttl_width;
                        let fill = " ".repeat(fill_len);
                        let opts_str = if options.is_empty() { "[]".to_string() }
                            else { format!("[{}]", options.iter().map(|(c,d)| format!("{}: {:?}", c, d)).collect::<Vec<_>>().join(", ")) };
                        println!("{}{} + {} {} {} {} {}", type_padded, fill, udp_payload_size, extended_rcode, version, flags, opts_str);
                    }
                    row_idx += 1;
                }
            }
        }
    }

    if show_time {
        println!("Ran in {}ms", last_elapsed.as_millis());
    }
}
