fn get_system_nameservers() -> Result<Vec<(String, u16)>, String> {
    let content = std::fs::read_to_string("/etc/resolv.conf")
        .map_err(|e| format!("Failed to read /etc/resolv.conf: {}", e))?;
    let mut servers = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.starts_with("nameserver") {
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 { servers.push((parts[1].to_string(), 53u16)); }
        }
    }
    if servers.is_empty() { Err("No nameservers found".to_string()) } else { Ok(servers) }
}

fn parse_nameserver(s: &str) -> (String, u16) {
    if let Some(idx) = s.rfind(':') {
        let host = &s[..idx];
        let port_str = &s[idx+1..];
        if let Ok(port) = port_str.parse::<u16>() {
            return (host.to_string(), port);
        }
    }
    (s.to_string(), 53)
}

