#[derive(Debug, Clone, Copy, PartialEq)]
enum ColorMode { Always, Never, Automatic }

#[derive(Debug, Clone, Copy, PartialEq)]
enum OutputFormat { Text, Json, Short }

#[derive(Debug, Clone, Copy, PartialEq)]
enum Transport { Udp, Tcp, Tls, Https, Automatic }

#[derive(Debug, Clone, Copy, PartialEq)]
enum EdnsMode { Disable, Hide, Show }

#[derive(Debug, Clone)]
struct ProtocolTweaks {
    set_aa: bool,
    set_ad: bool,
    set_cd: bool,
    udp_payload_size: Option<u16>,
}

impl Default for ProtocolTweaks {
    fn default() -> Self { ProtocolTweaks { set_aa: false, set_ad: false, set_cd: false, udp_payload_size: None } }
}

#[derive(Debug, Clone)]
struct Options {
