                    "always" => ColorMode::Always,
                    "never" => ColorMode::Never,
                    _ => ColorMode::Automatic,
                };
            }
            s if s.starts_with("--colour") || s.starts_with("--color") => {
                // --colour VALUE form
                i += 1;
                if i >= args.len() { return Err("Option '--colour' requires argument".to_string()); }
                color = match args[i].to_ascii_lowercase().as_str() {
                    "always" => ColorMode::Always,
                    "never" => ColorMode::Never,
                    _ => ColorMode::Automatic,
                };
            }
            s if s.starts_with("--edns=") => {
                let val = s[7..].to_ascii_lowercase();
                edns = match val.as_str() {
                    "disable" => EdnsMode::Disable,
                    "show" => EdnsMode::Show,
                    _ => EdnsMode::Hide,
                };
            }
            s if s.starts_with("--txid=") => {
                txid = Some(s[7..].parse::<u16>().map_err(|_| format!("Invalid txid: {}", &s[7..]))?);
            }
            s if s.starts_with("--query=") => {
